/* ==========================================================================
   >>> EDIT THESE <<<
   ========================================================================== */
const CALENDAR_ID    = 'primary';
const SHEET_ID       = '1N-qE4v81o0uxyXxLFeCamHSkvALFQIixrES3K6-hE6c';
const PUBLIC_BASE    = 'https://condone-making-amount.ngrok-free.dev';
const CLINIC_NAME    = 'Smile Dental Clinic';
const CLINIC_ADDRESS = '12 Main Boulevard, Lahore';
const CLINIC_PHONE   = '+92 300 000 0000';
const TIMEZONE       = 'Asia/Karachi';
const BOOKING_URL    = 'http://localhost:3000';   // where patients BOOK (not n8n)
const CLINIC_WHATSAPP = '15551915007';   // the clinic's WhatsApp number, digits only with country code, e.g. 923001234567.
                               // Email buttons open this chat with the message ready. '' = buttons work as before.
const CANCEL_CUTOFF_HOURS = 4;                    // no self-service cancel inside this window
/* ========================================================================== */

const q = $input.first().json.query || {};
const action = String(q.action || 'confirm').toLowerCase();
if (!['confirm', 'cancel'].includes(action)) throw new Error('Unknown action');
if (!q.ref || !q.token) throw new Error('Missing ref or token');
// A cancel only goes through when it carries do=1, which only the "Yes, cancel it"
// button adds. A bare cancel link (or an email scanner that pre-fetches links)
// lands on a confirmation page instead of destroying the booking.
const doIt = String(q.do || '') === '1';
return [{ json: { CALENDAR_ID, SHEET_ID, PUBLIC_BASE, CLINIC_NAME, CLINIC_ADDRESS,
  CLINIC_PHONE, TIMEZONE, BOOKING_URL, CLINIC_WHATSAPP, CANCEL_CUTOFF_HOURS, doIt,
  action, ref: String(q.ref).trim(), token: String(q.token).trim() } }];

// --- shared helpers -------------------------------------------------------
const toMin  = t => { const [h,m] = String(t).split(':').map(Number); return h*60 + (m||0); };
const toHHMM = m => `${String(Math.floor(m/60)).padStart(2,'0')}:${String(m%60).padStart(2,'0')}`;
const parts  = (isoStr, tz) => {
  const f = new Intl.DateTimeFormat('en-CA', { timeZone: tz, year:'numeric', month:'2-digit',
    day:'2-digit', hour:'2-digit', minute:'2-digit', hour12:false });
  const p = Object.fromEntries(f.formatToParts(new Date(isoStr)).map(x => [x.type, x.value]));
  return { date: `${p.year}-${p.month}-${p.day}`, min: (Number(p.hour) % 24) * 60 + Number(p.minute) };
};
const prettyDate = (d, tz) => new Date(d + 'T12:00:00Z')
  .toLocaleDateString('en-GB', { timeZone: tz, weekday:'long', day:'numeric', month:'long', year:'numeric' });
const pretty12 = t => { const [h,m] = String(t).split(':').map(Number);
  return `${((h+11)%12)+1}:${String(m).padStart(2,'0')} ${h>=12?'PM':'AM'}`; };
const busyBlocks = (fb, calId, day, tz) => {
  const cal = fb.calendars || {};
  const raw = (cal[calId] && cal[calId].busy) || (Object.values(cal)[0] || {}).busy || [];
  const out = [];
  for (const b of raw) {
    const s = parts(b.start, tz), e = parts(b.end, tz);
    if (e.date < day || s.date > day) continue;
    out.push([ s.date < day ? 0 : s.min, e.date > day ? 1440 : e.min ]);
  }
  return out;
};
