const p    = $('Parse Link').first().json;
const rows = ($input.first().json.values) || [];
const bad  = (reason, appt) => [{ json: { ...p, ok: false, reason, appt: appt || null } }];

// A row is identified by reference AND token together. References are short
// and can repeat; matching on the reference alone acts on the first row that
// shares it, which can be a different patient's booking.
let idx = -1, refSeen = false;
for (let i = 0; i < rows.length; i++) {
  if (String(rows[i][0] || '').trim() !== p.ref) continue;
  refSeen = true;
  if (String(rows[i][13] || '').trim() === p.token) { idx = i; break; }
}
if (idx < 0) return bad(refSeen ? 'bad-token' : 'not-found');

const r = rows[idx];

const appt = { ref:r[0], serviceName:r[4], date:r[5], time:r[6], duration:Number(r[7]) || 30,
               name:r[8], phone:r[9], email:r[10], eventId:r[12], price:r[16],
               doctorName: String(r[19] || '').trim(),
               calendarId: String(r[20] || '').trim() || p.CALENDAR_ID };   // each doctor has their own calendar
const status = String(r[2] || '').toUpperCase();
if (status === 'CANCELLED') return bad('cancelled', appt);
if (status === 'EXPIRED')   return bad('expired', appt);
if (status === 'CONFIRMED' && p.action === 'confirm') return bad('already-confirmed', appt);

// ---- how long until the appointment, in clinic time ----
const off = (() => {
  const s = new Intl.DateTimeFormat('en-US', { timeZone: p.TIMEZONE, timeZoneName: 'longOffset' })
    .formatToParts(new Date()).find(x => x.type === 'timeZoneName').value.replace('GMT', '');
  return s || '+00:00';
})();
const when = Date.parse(`${appt.date}T${appt.time}:00${off}`);
const hrs  = when ? (when - Date.now()) / 3600000 : 999;

// An appointment that has already happened can't be confirmed or cancelled —
// otherwise a stale link in an old email corrupts the clinic's numbers.
if (hrs < -1) return bad('past', appt);

// Too close to the appointment: the clinic can no longer refill the slot, so
// make the patient phone instead of silently dropping it.
if (p.action === 'cancel' && hrs < Number(p.CANCEL_CUTOFF_HOURS || 0))
  return bad('too-late', appt);

// Ask before destroying anything. Routed through the error branch so the
// workflow shape is unchanged.
if (p.action === 'cancel' && !p.doIt) return bad('confirm-cancel', appt);

return [{ json: { ...p, ok: true, isConfirm: p.action === 'confirm', rowNumber: idx + 2, appt,
  prettyDate: prettyDate(appt.date, p.TIMEZONE), prettyTime: pretty12(appt.time) } }];

const page = (tone, title, body, extra) => {
  const bar = { good:'#047857', warn:'#B45309', bad:'#B91C1C' }[tone];
  return `<!DOCTYPE html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title>
<link href="https://fonts.googleapis.com/css2?family=Atkinson+Hyperlegible:wght@400;700&display=swap" rel="stylesheet">
<style>body{font-family:'Atkinson Hyperlegible',system-ui,sans-serif;background:#F2FBFD;color:#123F52;
margin:0;padding:24px;display:flex;align-items:center;justify-content:center;min-height:100vh;line-height:1.55}
.c{background:#fff;border:1px solid #CDE9F1;border-radius:20px;max-width:520px;width:100%;
box-shadow:0 12px 40px -18px rgba(18,63,82,.3);overflow:hidden}
.h{background:${bar};color:#fff;padding:26px 28px}.h h1{margin:0;font-size:21px}
.b{padding:28px}.b p{margin:0 0 15px}
table{width:100%;border-collapse:collapse;font-size:14px;margin:18px 0}
td{padding:10px 0;border-top:1px solid #EDF5F8}td:first-child{color:#4A6572}
td:last-child{text-align:right;font-weight:700}
.btn{display:block;text-align:center;background:#0E7490;color:#fff;text-decoration:none;
padding:14px;border-radius:12px;font-weight:700;margin-top:8px}
.f{font-size:12px;color:#4A6572;border-top:1px solid #EDF5F8;padding-top:16px;margin-top:22px}</style></head>
<body><div class="c"><div class="h"><h1>${title}</h1></div><div class="b">${body}
<div class="f">${extra || ''}</div></div></div></body></html>`;
};

const v  = $('Verify Booking').first().json;
const ev = $input.first().json;                    // patched Google event
const a  = v.appt;
const gcal = (() => {
  try {
    const s = new Date(ev.start.dateTime), e = new Date(ev.end.dateTime);
    const z = d => d.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
    return 'https://calendar.google.com/calendar/render?action=TEMPLATE'
      + `&text=${encodeURIComponent(a.serviceName + ' — ' + v.CLINIC_NAME)}`
      + `&dates=${z(s)}/${z(e)}`
      + `&location=${encodeURIComponent(v.CLINIC_ADDRESS)}`
      + `&details=${encodeURIComponent('Reference ' + a.ref + '. Please arrive 10 minutes early.')}`;
  } catch (err) { return ''; }
})();

const rows = `<table>
<tr><td>Treatment</td><td>${a.serviceName}</td></tr>
${a.doctorName ? `<tr><td>Dentist</td><td>${a.doctorName}</td></tr>` : ''}
<tr><td>Date</td><td>${v.prettyDate}</td></tr>
<tr><td>Time</td><td>${v.prettyTime}</td></tr>
<tr><td>Duration</td><td>${a.duration} minutes</td></tr>
<tr><td>Reference</td><td>${a.ref}</td></tr></table>`;

// Buttons open the clinic's WhatsApp chat with the message already typed; the patient just presses send.
const waDigits = String(v.CLINIC_WHATSAPP || '').replace(/\D/g, '');
const wa = text => waDigits.length >= 8 ? `https://wa.me/${waDigits}?text=${encodeURIComponent(text)}` : '';
const waCancel = wa(`I want to cancel my appointment. Reference: ${a.ref}`);
const cancelLink = `${v.PUBLIC_BASE}/webhook/booking-action?ref=${encodeURIComponent(a.ref)}`
                 + `&token=${encodeURIComponent(v.token)}&action=cancel`;

const html = page('good', 'Your appointment is confirmed',
  `<p>Thank you, <strong>${a.name}</strong>. We look forward to seeing you.</p>${rows}
   ${gcal ? `<a class="btn" href="${gcal}">Add to my calendar</a>` : ''}
   <p style="margin-top:20px;font-size:14px;text-align:center">
     <a href="${waCancel || cancelLink}" style="color:#4A6572">${waCancel ? 'Need to change or cancel? Message us on WhatsApp' : 'Need to cancel?'}</a></p>`,
  `Please arrive 10 minutes early.<br>${v.CLINIC_ADDRESS} &middot; ${v.CLINIC_PHONE}`);

const email = page('good', 'Appointment confirmed',
  `<p>Hello <strong>${a.name}</strong>, your appointment at ${v.CLINIC_NAME} is confirmed.</p>${rows}
   ${gcal ? `<a class="btn" href="${gcal}">Add to my calendar</a>` : ''}
   <p style="margin-top:18px;font-size:14px">Need to change it?
   <a href="${waCancel || cancelLink}">${waCancel ? 'Cancel or change on WhatsApp' : 'Cancel this appointment'}</a>.</p>`,
  `We will send you a reminder 24 hours and 2 hours before.<br>${v.CLINIC_ADDRESS} &middot; ${v.CLINIC_PHONE}`);

return [{ json: { ...v, html, email,
  subject: `Confirmed: ${a.serviceName} on ${v.prettyDate} at ${v.prettyTime}  [Ref: ${a.ref}]` } }];

