const v = $('Verify Booking').first().json, a = v.appt;
// Buttons open the clinic's WhatsApp chat with the message already typed; the patient just presses send.
const waDigits = String(v.CLINIC_WHATSAPP || '').replace(/\D/g, '');
const wa = text => waDigits.length >= 8 ? `https://wa.me/${waDigits}?text=${encodeURIComponent(text)}` : '';
const waBook = wa('I would like to book an appointment.');
const html = page('warn', 'Appointment cancelled',
  `<p>Your appointment on <strong>${v.prettyDate} at ${v.prettyTime}</strong> has been cancelled
   and the slot released for other patients.</p>
   <p>Changed your mind? You can book again any time.</p>
   <a class="btn" href="${waBook || v.BOOKING_URL}">${waBook ? 'Book again on WhatsApp' : 'Book a new appointment'}</a>`,
  `${v.CLINIC_NAME} &middot; ${v.CLINIC_PHONE}`);
return [{ json: { ...v, html } }];

