const v = $('Verify Booking').first().json;
const a = v.appt || {};
// Buttons open the clinic's WhatsApp chat with the message already typed; the patient just presses send.
const waDigits = String(v.CLINIC_WHATSAPP || '').replace(/\D/g, '');
const wa = text => waDigits.length >= 8 ? `https://wa.me/${waDigits}?text=${encodeURIComponent(text)}` : '';
const waBook = wa('I would like to book an appointment.');
const foot = `${v.CLINIC_NAME} &middot; ${v.CLINIC_PHONE}`;
const when = (a.date && a.time)
  ? `${prettyDate(a.date, v.TIMEZONE)} at ${pretty12(a.time)}` : '';

// ---- "are you sure?" interstitial, not an error ----
if (v.reason === 'confirm-cancel') {
  const yes = `${v.PUBLIC_BASE}/webhook/booking-action?ref=${encodeURIComponent(v.ref)}`
            + `&token=${encodeURIComponent(v.token)}&action=cancel&do=1`;
  const html = page('warn', 'Cancel this appointment?',
    `<p>You are about to cancel:</p>
     <table>
       <tr><td>Treatment</td><td>${a.serviceName || ''}</td></tr>
       <tr><td>When</td><td>${when}</td></tr>
       <tr><td>Reference</td><td>${a.ref || v.ref}</td></tr>
     </table>
     <p style="font-size:14px;color:#4A6572">The slot will be released for another patient. This cannot be undone.</p>
     <a class="btn" style="background:#B91C1C" href="${yes}">Yes, cancel it</a>
     <p style="font-size:14px;color:#4A6572;text-align:center;margin-top:16px">To keep your appointment, just close this page. Nothing has been changed.</p>`,
    foot);
  return [{ json: { ...v, html } }];
}

const M = {
  'not-found':        ['bad',  'Booking not found',      'We could not find that reference. Please check the link in your email, or call the clinic.'],
  'bad-token':        ['bad',  'This link is not valid', 'The security code in this link does not match. Please use the original email, or call the clinic.'],
  'expired':          ['warn', 'This hold has expired',  'The 30-minute hold ran out and the slot was released. Please book again — it only takes a minute.'],
  'cancelled':        ['warn', 'Already cancelled',      'This appointment was already cancelled. The slot is free for someone else.'],
  'already-confirmed':['good', 'Already confirmed',      'Good news — this appointment is already confirmed. Nothing more to do.'],
  'past':             ['warn', 'This appointment has passed', 'That date has already gone by, so this link no longer does anything.'],
  'too-late':         ['warn', 'Too close to cancel online', `Your appointment is ${when ? 'on ' + when : 'very soon'}, which is inside our ${v.CANCEL_CUTOFF_HOURS}-hour window. Please phone us on ${v.CLINIC_PHONE} so we can offer the slot to someone else.`]
};
const [tone, title, msg] = M[v.reason] || ['bad', 'Something went wrong', 'Please call the clinic and we will sort it out.'];
const cta = v.reason === 'too-late'
  ? `<a class="btn" href="tel:${String(v.CLINIC_PHONE).replace(/[^0-9+]/g,'')}">Call the clinic</a>`
  : `<a class="btn" href="${waBook || v.BOOKING_URL}">${waBook ? 'Book on WhatsApp' : 'Book an appointment'}</a>`;
const html = page(tone, title, `<p>${msg}</p>${cta}`, foot);
return [{ json: { ...v, html } }];
